import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long res = (n / 2) + (n / 3) - (n / 6) + (n / 42)
                  +(n / 5) + (n / 7) + (n/ 30) + (n / 70) + (n / 105)
                  -(n / 10) - (n / 15) - (n / 14) - (n / 21) - (n / 35) - (n / 210);
        System.out.println(n - res);
    }
}
